def blocks(g):
    h,w=len(g),len(g[0]); res=[]
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==g[r][c+1]==g[r+1][c]==g[r+1][c+1]==2: res.append((r,c))
    return sorted(res)
rows_=[]
for key in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    I=G[key+' input']; O=G[key+' output']
    B=blocks(I); H,W=len(I),len(I[0])
    for b in B:
        r,c=b
        feats=dict(H=H,W=W,r=r,c=c,
                   dist_top=r, dist_bot=H-r-2, dist_left=c, dist_right=W-c-2,
                   edge_t=r==0, edge_b=r+1==H-1, edge_l=c==0, edge_r=c+1==W-1,
                   par_r=r%2, par_c=c%2,
                   rc=(r+c)%2, rm=(r-c)%2,
                   sum_rc=(r+c), diff_rc=(r-c))
        # diagonal partners: other block on main diag (dr=dc) or anti diag
        has_diag=any(abs(br-b[0])==abs(bc-b[1]) and (br-r)+(bc-c)!=0 for br,bc in B if (br,bc)!=b)
        # nearest block distance Chebyshev
        nb=min(((max(abs(br-r),abs(bc-c))) for br,bc in B if (br,bc)!=b), default=99)
        # horizontal gap to next block in same row
        hb=sorted(b for rr,b in enumerate([]) )
        sb=[bb for bb in B if bb[0]==r]
        hb=min([abs(bb[1]-c) for bb in sb if bb!=(r,c)], default=99)
        fb=[bb for bb in B if bb[0]==r+1]
        vb=min([abs(bb[1]-c) for bb in fb if bb!=(r,c)], default=99)
        feats['has_diag']=has_diag; feats['nb']=nb; feats['hgap']=hb; feats['vgap']=vb
        # is it the leftmost in its row?
        feats['leftmost_in_row']=min(bb[1] for bb in sb)==c if sb else False
        rows_.append((feats,'C' if O[b[0]][b[1]]==8 else 'K',key))
