import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def blocks(g):
    h,w=len(g),len(g[0]); res=[]
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==g[r][c+1]==g[r+1][c]==g[r+1][c+1]==2: res.append((r,c))
    return sorted(res)
rows_= []
for key in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    I=G[key+' input']; O=G[key+' output']
    B=blocks(I); H,W=len(I),len(I[0])
    for b in B:
        r,c=b
        Bset=set(B)
        # nearest block Chebyshev, and min Manhattan, and existence of diagonal neighbor
        def nb(br,bc):
            return ((br,bc) in Bset and ((abs(br-r)==1 and abs(bc-c)==1) or (abs(br-r)+abs(bc-c)==min(abs(br-r),abs(bc-c))) ) )
        diag=any(abs(br-r)==abs(bc-c) and abs(br-r)>0 for br,bc in Bset if (br,bc)!=b)
        orth=any(max(abs(br-r),abs(bc-c))==1 for br,bc in Bset if (br,bc)!=b)
        # vertical neighbor (directly above/below)
        vert=(r+1 in [br for br,_ in Bset] and any(br==r+1 and bc'==c or br==r-1 and bc'==c for bc' in [c]))
        vert=any(((r+1,bc) in Bset or (r-1,bc) in Bset or (r,bc+1) in Bset or (r,bc-1) in Bset) for bc in [c])
        hcount=sum(1 for bc in [c2] for c2 in [c] )  # placeholder
        hcount=sum(1 for rr,cc in Bset if rr==r)
        vcount=sum(1 for rr,cc in Bset if cc==c)
        rows_.append(dict(r=r,c=c,dist_top=r,dist_bot=H-r-2,dist_left=c,dist_right=W-c-2,
